<script setup>
import { computed, ref } from 'vue'
import { ArrowRight, CalendarClock, Check, ChevronRight, Clock3, Database, GitBranch, ListChecks, MoreHorizontal, Pause, Play, Plus, RefreshCw, RotateCw, Search, Square, Timer, X, Zap } from 'lucide-vue-next'

const tasks = ref([
  { id: 'task-9f2a', title: '智能体竞品分析', status: 'running', priority: 'P1', source: '定时任务', ticket: 'TICK-1284', elapsed: '3 分 12 秒', progress: 62, model: 'deepseek-v4-pro', schedule: '每日 09:00', workspace: '生产', owner: '王敏' },
  { id: 'task-4aa8', title: '周报数据汇总', status: 'running', priority: 'P2', source: '定时任务', ticket: 'TICK-1290', elapsed: '1 分 40 秒', progress: 28, model: 'deepseek-v4-pro', schedule: '每周一 18:00', workspace: '生产', owner: '李楠' },
  { id: 'task-71c0', title: '代码审查 · 合并请求 482', status: 'approval', priority: 'P0', source: '代码仓库', ticket: 'TICK-1301', elapsed: '等待 4 分钟', progress: 0, model: 'claude-3.5', schedule: '事件触发', workspace: '生产', owner: '陈森' },
  { id: 'task-2d13', title: '客户访谈摘要', status: 'approval', priority: 'P2', source: '协作消息', ticket: 'TICK-1304', elapsed: '等待 11 分钟', progress: 0, model: 'gpt-4.1', schedule: '命令触发', workspace: '分析', owner: '刘洋' },
  { id: 'task-7e82', title: '依赖漏洞巡检', status: 'queued', priority: 'P1', source: '定时任务', ticket: 'TICK-1275', elapsed: '—', progress: 0, model: 'deepseek-v4-pro', schedule: '每日 02:00', workspace: '生产', owner: '安全组' },
  { id: 'task-c991', title: '渠道归因回测', status: 'queued', priority: 'P2', source: '手动触发', ticket: 'TICK-1299', elapsed: '—', progress: 0, model: 'gpt-4.1', schedule: '手动', workspace: '分析', owner: '数据组' },
  { id: 'task-82bd', title: '政策解读简报', status: 'paused', priority: 'P2', source: '定时任务', ticket: 'TICK-1266', elapsed: '2 分 05 秒', progress: 44, model: 'claude-3.5', schedule: '工作日 08:00', workspace: '生产', owner: '王敏' },
  { id: 'task-4f11', title: '支付模块重构测试', status: 'done', priority: 'P1', source: '手动触发', ticket: 'TICK-1268', elapsed: '5 分 12 秒', progress: 100, model: 'deepseek-v4-pro', schedule: '手动', workspace: '生产', owner: '陈森' },
  { id: 'task-1271', title: '回归用例生成', status: 'failed', priority: 'P1', source: '手动触发', ticket: 'TICK-1271', elapsed: '8 分 02 秒', progress: 100, model: 'claude-3.5', schedule: '手动', workspace: '生产', owner: '质量组' },
  { id: 'task-1268', title: '周报数据汇总 · 补跑', status: 'timeout', priority: 'P2', source: '定时任务', ticket: 'TICK-1268', elapsed: '30 分钟', progress: 77, model: 'deepseek-v4-pro', schedule: '每周一 18:00', workspace: '生产', owner: '李楠' },
])

const selectedId = ref('task-9f2a')
const filter = ref('all')
const detailTab = ref('overview')
const toast = ref('')
const selectedTask = computed(() => tasks.value.find(task => task.id === selectedId.value) || tasks.value[0])
const visibleTasks = computed(() => tasks.value.filter(task => filter.value === 'all' || (filter.value === 'failed' ? ['failed', 'timeout'].includes(task.status) : task.status === filter.value)))
const counts = computed(() => ({
  all: tasks.value.length,
  running: tasks.value.filter(task => task.status === 'running').length,
  approval: tasks.value.filter(task => task.status === 'approval').length,
  queued: tasks.value.filter(task => task.status === 'queued').length,
  failed: tasks.value.filter(task => ['failed', 'timeout'].includes(task.status)).length,
}))

const statusLabels = { running: '运行中', approval: '等待审批', queued: '排队', paused: '暂停', done: '已完成', failed: '失败', timeout: '已超时' }
const sourceIcons = { '代码仓库': '库', '协作消息': '协', '定时任务': '时', '手动触发': '手' }

function statusLabel(status) { return statusLabels[status] || status }
function displayModel(model) { return { 'deepseek-v4-pro': '深度求索第四代', 'claude-3.5': '协作模型第三代', 'gpt-4.1': '通用模型第四代' }[model] || model }
function formatTaskId(id) { return id.replace('task-', '任务-') }
function sourceLabel(source) { return source }
function formatTicket(ticket) { return ticket.replace('TICK-', '工单-') }
function notify(message) {
  toast.value = message
  window.clearTimeout(notify.timer)
  notify.timer = window.setTimeout(() => { toast.value = '' }, 2400)
}
function createTask() {
  const id = `task-${Math.random().toString(16).slice(2, 6)}`
  tasks.value.unshift({ id, title: '新建编排任务', status: 'queued', priority: 'P2', source: '手动触发', ticket: id.toUpperCase(), elapsed: '—', progress: 0, model: 'deepseek-v4-pro', schedule: '手动', workspace: '生产', owner: '当前用户' })
  selectedId.value = id
  notify('新任务已加入队列')
}
function toggleRun() {
  const task = selectedTask.value
  if (task.status === 'running') {
    task.status = 'paused'
    notify('任务已暂停，可从检查点恢复')
  } else {
    task.status = 'running'
    notify('任务已恢复执行')
  }
}
function retryTask() {
  selectedTask.value.status = 'queued'
  selectedTask.value.progress = 0
  notify('任务已重新排队')
}
</script>

<template>
  <div class="task-orchestration-page">
    <header class="task-page-header">
      <div class="task-page-title"><div class="task-page-icon"><ListChecks :size="25" /></div><div><h1>运行状态</h1><p>任务编排 · 模板 / 调度 / 触发 / 可靠性</p></div></div>
      <div class="task-page-actions"><div class="task-concurrency"><span class="task-live-dot"></span><span>全局并发</span><strong>5</strong><span>/</span><b>16</b><i><em></em></i></div><div class="task-workspace">工作空间：<strong>生产</strong></div><button class="task-primary-button" @click="createTask"><Plus :size="18" />新建任务</button></div>
    </header>

    <section class="task-kpi-grid">
      <article class="task-kpi"><div class="task-kpi-label"><i class="kpi-blue"></i>队列深度</div><strong>6</strong><small>运行 2 · 排队 2 · 待审批 2</small></article>
      <article class="task-kpi"><div class="task-kpi-label"><i class="kpi-green"></i>处理速率</div><strong>12.4 <small>任务/分</small></strong><div class="kpi-foot">较昨日 <b>+18%</b><svg viewBox="0 0 160 38"><path d="M2 31 L28 23 L55 27 L82 12 L108 5 L137 9 L158 2" /></svg></div></article>
      <article class="task-kpi"><div class="task-kpi-label"><i class="kpi-red"></i>错误率</div><strong class="danger">3.8<small>%</small></strong><div class="kpi-foot danger-text"><b>较昨日 +1.1pt</b><span>重试中 2</span><svg viewBox="0 0 160 38"><path d="M2 31 L28 23 L55 27 L82 16 L108 13 L137 7 L158 1" /></svg></div></article>
      <article class="task-kpi"><div class="task-kpi-label"><i class="kpi-amber"></i>等待审批</div><strong class="warning">2</strong><small>P0 高危 1 · 点击处理</small></article>
    </section>

    <section class="task-workspace-grid">
      <section class="task-list-card">
      <div class="task-card-heading"><h2>任务列表</h2><small>共 {{ counts.all }}</small></div>
        <div class="task-filter-tabs"><button :class="{ active: filter === 'all' }" @click="filter = 'all'">全部 <b>{{ counts.all }}</b></button><button :class="{ active: filter === 'running' }" @click="filter = 'running'">运行中 <b>{{ counts.running }}</b></button><button :class="{ active: filter === 'approval' }" @click="filter = 'approval'">待审批 <b>{{ counts.approval }}</b></button><button :class="{ active: filter === 'queued' }" @click="filter = 'queued'">排队 <b>{{ counts.queued }}</b></button><button :class="{ active: filter === 'failed' }" @click="filter = 'failed'">失败/死信 <b>{{ counts.failed }}</b></button></div>
        <div class="task-list-scroll">
          <button v-for="task in visibleTasks" :key="task.id" class="task-row" :class="{ selected: selectedId === task.id }" @click="selectedId = task.id; detailTab = 'overview'"><div class="task-row-top"><span class="task-status" :class="task.status"><i></i>{{ statusLabel(task.status) }}</span><strong>{{ task.title }}</strong><em>{{ task.priority }}</em></div><div class="task-row-meta"><span class="source-icon" :class="task.source === 'Slack' ? 'slack' : task.source === 'GitHub' ? 'github' : ''">{{ sourceIcons[task.source] || '手' }}</span><span>{{ sourceLabel(task.source) }}</span><span class="task-ticket">{{ formatTicket(task.ticket) }}</span><span class="task-row-time">{{ task.elapsed }}</span></div><div v-if="task.status === 'running' || task.status === 'paused'" class="task-progress"><i :style="{ width: `${task.progress}%` }"></i></div></button>
          <div v-if="!visibleTasks.length" class="task-empty"><Search :size="18" />当前筛选没有任务</div>
        </div>
      </section>

      <section class="task-detail-card">
        <header class="task-detail-heading"><div><div class="task-detail-title"><h2>{{ selectedTask.title }}</h2><span class="task-status" :class="selectedTask.status"><i></i>{{ statusLabel(selectedTask.status) }}</span><span class="task-chip">{{ displayModel(selectedTask.model) }}</span><span class="task-chip">{{ selectedTask.schedule }}</span><span class="task-chip">{{ formatTaskId(selectedTask.id) }}</span></div></div><MoreHorizontal :size="20" /></header>
        <nav class="task-detail-tabs"><button :class="{ active: detailTab === 'overview' }" @click="detailTab = 'overview'">概览与状态机</button><button :class="{ active: detailTab === 'retries' }" @click="detailTab = 'retries'">重试 · 死信 · 降级</button><button :class="{ active: detailTab === 'dag' }" @click="detailTab = 'dag'">任务依赖</button><button :class="{ active: detailTab === 'outputs' }" @click="detailTab = 'outputs'">输出与交付</button></nav>
        <div v-if="detailTab === 'overview'" class="task-detail-scroll">
          <section class="state-machine"><h3>任务状态流转 · 审批后暂停，中断后可从恢复点继续</h3><div class="state-flow"><span>排队</span><b>→</b><span class="current">运行中</span><b>→</b><span>等待审批</span><b>↔</b><span>暂停</span><b>→</b><div class="state-outcomes"><span>已完成</span><span>失败</span><span>已取消</span><span>已超时</span></div></div><p>当前：<strong>{{ statusLabel(selectedTask.status) }}</strong><i>·</i> 暂停可恢复<i>·</i> 等待审批可暂停</p></section>
          <div class="task-actions"><button class="task-ghost-button" @click="toggleRun"><Pause v-if="selectedTask.status === 'running'" :size="15" /><Play v-else :size="15" />{{ selectedTask.status === 'running' ? '暂停' : '恢复' }}</button><button class="task-danger-button" @click="selectedTask.status = 'failed'; notify('任务已取消')"><Square :size="14" />取消</button></div>
          <section class="task-info-section"><h3>运行信息</h3><div class="task-info-grid"><div><small>运行时长</small><strong>{{ selectedTask.elapsed === '—' ? '—' : selectedTask.elapsed }}</strong></div><div><small>本次成本</small><strong>$0.42</strong></div><div><small>重试</small><strong>0 / 3</strong></div><div><small>下次运行</small><strong>明日 09:00</strong></div><div><small>长时间运行</small><strong>可中断恢复</strong></div><div><small>编排模式</small><strong>顺序执行</strong></div></div></section>
          <section class="task-info-section"><h3>任务信息</h3><div class="task-meta-pills"><span>工单 <b>{{ formatTicket(selectedTask.ticket) }}</b></span><span>优先级 <b>{{ selectedTask.priority }}</b></span><span>负责人 <b>{{ selectedTask.owner }}</b></span><span>工作空间 <b>{{ selectedTask.workspace }}</b></span></div></section>
          <section class="task-info-section"><h3>最近执行记录</h3><div class="task-history"><div><span>今日 09:00</span><b class="task-status done"><i></i>已完成</b><span>4m58s</span><span>$0.38</span><button @click="retryTask">重放</button></div><div><span>昨日 09:00</span><b class="task-status done"><i></i>已完成</b><span>5m21s</span><span>$0.41</span><button @click="retryTask">重放</button></div><div><span>04-17 09:00</span><b class="task-status failed"><i></i>失败</b><span>2m10s</span><span>$0.12</span><button @click="retryTask">重放</button></div></div></section>
        </div>
        <div v-else-if="detailTab === 'retries'" class="task-placeholder"><RotateCw :size="22" /><h3>重试与死信策略</h3><p>最大重试次数 3 次 · 指数退避 · 超限后进入死信队列。</p><button class="task-ghost-button" @click="retryTask">立即重试</button></div>
        <div v-else-if="detailTab === 'dag'" class="task-placeholder"><GitBranch :size="22" /><h3>任务依赖关系</h3><p>当前任务依赖：数据准备 → 分析执行 → 结果校验 → 输出交付。</p></div>
        <div v-else class="task-placeholder"><Database :size="22" /><h3>输出与交付</h3><p>当前运行尚未生成新的交付物。</p></div>
      </section>
    </section>

    <section class="task-lower-grid">
      <section class="task-wide-card"><div class="task-card-heading"><h2>调度 · 触发 · 并发</h2><small>跟随选中任务</small></div><div class="trigger-card"><div class="trigger-title"><CalendarClock :size="18" />定时调度规则 <b>启用</b></div><div class="cron-line"><code>0 9 * * 1-5</code><span>工作日 09:00</span></div><div class="trigger-lines"><div><span>时区</span><b>北京时间</b></div><div><span>单次预算上限</span><b>$5.00</b></div><div><span>输出目的地</span><b>协作平台 · 报告频道</b></div><div><span>错过调度</span><b>跳过并记录（不补跑）</b></div><div><span>下次运行</span><b class="blue-text">明日 09:00</b></div></div></div><div class="trigger-card event-card"><div class="trigger-title"><Zap :size="18" />事件触发源 <b>6 个</b></div><div class="event-source"><span class="source-icon github">库</span>代码托管 · 新建合并请求 <b>已验证</b></div><div class="event-source"><span class="source-icon slack">协</span>协作平台 · 命令触发 <b>已验证</b></div><div class="event-source"><span class="source-icon">项</span>项目管理 · 新建问题 <b>待验证</b></div><button class="add-trigger">＋添加触发源</button></div><div class="trigger-card concurrency-card"><div class="trigger-title"><ArrowRight :size="18" />并发控制 <b>限流保护开</b></div><div class="trigger-lines"><div><span>全局并发上限</span><b>16</b></div><div><span>单任务并发上限</span><b>3</b></div><div><span>每轮工具并发</span><b>8</b></div><div><span>当前占用</span><b>5 / 16（31%）</b></div></div><div class="concurrency-bar"><i></i></div><div class="limit-note">超限策略 <b>排队等待 + 429 指数退避</b></div></div></section>
      <section class="task-bottom-grid"><div class="task-wide-card"><div class="task-card-heading"><h2>死信队列</h2><small>永久失败 · 需人工排查</small></div><div class="dead-header"><span>任务</span><span>错误原因</span><span>重试</span><span>进入时间</span><span>操作</span></div><div class="dead-row"><strong>客户访谈摘要 · 批量(48)</strong><b>模型持续限流 429 · 重试耗尽</b><span>5 / 5</span><span>09:12</span><span><button @click="retryTask">重放</button><button>丢弃</button></span></div><div class="dead-row"><strong>告警回放 · 夜间批</strong><b>沙箱崩溃 · 不可恢复</b><span>3 / 3</span><span>03:47</span><span><button @click="retryTask">重放</button><button>丢弃</button></span></div></div><div class="task-wide-card"><div class="task-card-heading"><h2>即将运行</h2><small>北京时间</small></div><div class="upcoming-row"><strong>09:00</strong><span>竞品分析 · 智能体</span><small>定时 · P1</small></div><div class="upcoming-row"><strong>18:00</strong><span>周报数据汇总</span><small>定时 · P2</small></div><div class="upcoming-row"><strong>02:00</strong><span>依赖漏洞巡检</span><small>定时 · P1</small></div><div class="upcoming-row"><strong>08:00</strong><span>政策解读简报（已暂停）</span><small>暂停</small></div></div></section>
    </section>

    <div v-if="toast" class="task-toast"><Check :size="15" />{{ toast }}</div>
  </div>
</template>

<style scoped>
